//! Signing and verifying board items with the device key (ECDSA P-256, as generated by identity).

use std::sync::Arc;

use ring::rand::SystemRandom;
use ring::signature::{EcdsaKeyPair, UnparsedPublicKey, ECDSA_P256_SHA256_ASN1, ECDSA_P256_SHA256_ASN1_SIGNING};
use x509_parser::prelude::{FromDer, X509Certificate};

use super::model::{BoardItem, ItemKind};
use crate::error::{MunikoError, Result};
use crate::identity::Identity;
use crate::messages::board as msg;
use crate::util::fingerprint::fingerprint;
use crate::util::time::unix_now;

/// Creates items authored and signed by this device.
pub struct ItemSigner {
    identity: Arc<Identity>,
}

impl ItemSigner {
    pub fn new(identity: Arc<Identity>) -> Self {
        Self { identity }
    }

    pub fn device_id(&self) -> &str {
        self.identity.device_id()
    }

    pub fn cert_der(&self) -> &[u8] {
        self.identity.cert_der()
    }

    pub fn sign(&self, board_id: &str, kind: ItemKind) -> Result<BoardItem> {
        let mut item = BoardItem {
            id: uuid::Uuid::now_v7().to_string(),
            board_id: board_id.to_string(),
            author_id: self.identity.device_id().to_string(),
            created_at: unix_now(),
            kind,
            signature: Vec::new(),
        };
        item.signature = self.signature_for(&item)?;
        Ok(item)
    }

    fn signature_for(&self, item: &BoardItem) -> Result<Vec<u8>> {
        let rng = SystemRandom::new();
        let key = EcdsaKeyPair::from_pkcs8(&ECDSA_P256_SHA256_ASN1_SIGNING, self.identity.key_der(), &rng)
            .map_err(|_| MunikoError::Identity(msg::BAD_SIGNING_KEY.to_string()))?;
        let signature = key
            .sign(&rng, &item.canonical_bytes())
            .map_err(|_| MunikoError::Identity(msg::BAD_SIGNING_KEY.to_string()))?;
        Ok(signature.as_ref().to_vec())
    }
}

/// True when `cert_der` is the certificate of `item.author_id` and the signature covers the item.
pub fn verify_item(item: &BoardItem, cert_der: &[u8]) -> bool {
    if fingerprint(cert_der) != item.author_id {
        return false;
    }
    let Some(public_key) = public_key_of(cert_der) else {
        return false;
    };
    UnparsedPublicKey::new(&ECDSA_P256_SHA256_ASN1, public_key)
        .verify(&item.canonical_bytes(), &item.signature)
        .is_ok()
}

fn public_key_of(cert_der: &[u8]) -> Option<Vec<u8>> {
    let (_, certificate) = X509Certificate::from_der(cert_der).ok()?;
    Some(certificate.public_key().subject_public_key.data.to_vec())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::util::test_support::shared_test_identity;

    fn text(text: &str) -> ItemKind {
        ItemKind::Text { text: text.into() }
    }

    #[test]
    fn signature_round_trips() {
        let identity = shared_test_identity();
        let item = ItemSigner::new(identity.clone()).sign("board", text("hi")).unwrap();
        assert!(verify_item(&item, identity.cert_der()));
    }

    #[test]
    fn tampered_content_is_rejected() {
        let identity = shared_test_identity();
        let mut item = ItemSigner::new(identity.clone()).sign("board", text("hi")).unwrap();
        item.kind = text("changed");
        assert!(!verify_item(&item, identity.cert_der()));
    }

    #[test]
    fn tampered_author_or_foreign_cert_is_rejected() {
        let identity = shared_test_identity();
        let other = shared_test_identity();
        let item = ItemSigner::new(identity.clone()).sign("board", text("hi")).unwrap();
        assert!(!verify_item(&item, other.cert_der()));
        let mut forged = item.clone();
        forged.author_id = other.device_id().to_string();
        assert!(!verify_item(&forged, other.cert_der()));
    }
}
